CREATE TYPE public.app_role AS ENUM ('admin','teacher','student');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar text NOT NULL DEFAULT '🦉', level text NOT NULL DEFAULT 'Secundaria', goal text NOT NULL DEFAULT '', daily_xp integer NOT NULL DEFAULT 50 CHECK (daily_xp BETWEEN 1 AND 1000));
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE SET NULL, teacher_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), email text NOT NULL UNIQUE CHECK (email=lower(email)), institution text NOT NULL DEFAULT '', level text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.students TO authenticated;
GRANT ALL ON public.students TO service_role;
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
CREATE POLICY students_read ON public.students FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher')));
CREATE POLICY students_create ON public.students FOR INSERT TO authenticated WITH CHECK (teacher_id=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'teacher')));
CREATE POLICY students_update ON public.students FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin') OR (teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher'))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher')));
CREATE POLICY students_delete ON public.students FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin') OR (teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher')));
CREATE POLICY profiles_teacher_read ON public.profiles FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.students s WHERE s.user_id=profiles.id AND s.teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher')));
CREATE TABLE public.practice_attempts (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, deck_id text NOT NULL, title text NOT NULL, score integer NOT NULL CHECK(score BETWEEN 0 AND 100), question_count integer NOT NULL CHECK(question_count BETWEEN 1 AND 200), answers jsonb NOT NULL DEFAULT '[]', verified_scoring boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.practice_attempts TO authenticated;
GRANT ALL ON public.practice_attempts TO service_role;
ALTER TABLE public.practice_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempts_read ON public.practice_attempts FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.students s WHERE s.user_id=practice_attempts.user_id AND s.teacher_id=auth.uid() AND public.has_role(auth.uid(),'teacher')));
CREATE INDEX attempts_user_time ON public.practice_attempts(user_id,created_at DESC);
CREATE INDEX students_teacher ON public.students(teacher_id);
CREATE TABLE public.teacher_access (email text PRIMARY KEY CHECK(email=lower(email)), created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.teacher_access TO authenticated;
GRANT ALL ON public.teacher_access TO service_role;
ALTER TABLE public.teacher_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_access_admin ON public.teacher_access FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.initialize_student_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.profiles(id,display_name) VALUES(new.id, coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','')) ON CONFLICT(id) DO NOTHING;
IF new.email_confirmed_at IS NOT NULL THEN
IF lower(new.email)='maxi.salsa@gmail.com' THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'admin') ON CONFLICT DO NOTHING; END IF;
IF EXISTS(SELECT 1 FROM public.teacher_access WHERE email=lower(new.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'teacher') ON CONFLICT DO NOTHING; END IF;
UPDATE public.students SET user_id=new.id WHERE email=lower(new.email) AND user_id IS NULL;
END IF;
RETURN new; END $$;
CREATE TRIGGER initialize_account AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_student_account();
CREATE FUNCTION public.claim_student_registration() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE verified_email text; BEGIN
SELECT lower(email) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL;
IF verified_email IS NULL THEN RETURN; END IF;
UPDATE public.students SET user_id=auth.uid() WHERE email=verified_email AND user_id IS NULL;
END $$;
REVOKE ALL ON FUNCTION public.claim_student_registration() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_student_registration() TO authenticated;
REVOKE ALL ON FUNCTION public.initialize_student_account() FROM PUBLIC,anon,authenticated;